mapper.select:
select
dish.*,
dishType.type_name
from dish dish
left join dish_type dishType on dish.type_id = dishType.id

    and dish.id = #{id}
    and dish.dish_name like concat('%',#{dishName},'%')
    and dish.dish_img = #{dishImg}
    and dish.dish_info = #{dishInfo}
    and dish.taste = #{taste}
    and dish.price = #{price}
    and dish.create_time = #{createTime}
    and dish.status = #{status}
    and dish.type_id = #{typeId}
    and dishType.type_name like concat('%',#{typeName},'%')

order by id desc

    limit #{current},#{pageSize}

select count(*) from dish dish
left join dish_type dishType on dish.type_id = dishType.id

    and dish.id = #{id}
    and dish.dish_name like concat('%',#{dishName},'%')
    and dish.dish_img = #{dishImg}
    and dish.dish_info = #{dishInfo}
    and dish.taste = #{taste}
    and dish.price = #{price}
    and dish.create_time = #{createTime}
    and dish.status = #{status}
    and dish.type_id = #{typeId}
    and dishType.type_name like concat('%',#{typeName},'%')
